#include <global.h>
struct UnderTakerPlace {u16 weight,place;u32 unused;};
struct UnderTakerData {u16 interval,increase,decrease,randomMax,maximum,duration;s32 startFlag,stepFlag,countFlag,placeFlag,timeFlag,endFlag;u32 unused,progressFirst,progressLast;s32 sideFlag;UnderTakerPlace places[7];};
struct WorldmapXD {u8 pad[0x94];s32 firstFlag;u8 pad2[0x190-0x98];s32 secondFlag;};
extern "C" {
extern UnderTakerData *undertakerdata;extern WorldmapXD *worldmapXD_data;extern u8 *flag_etc;
u32 GSflagGet(s32);void GSflagSet(s32,u32);u8 GSflagTest(s32);s32 HSD_Rand();u8 darkpokemonCheckUnderTaker();u16 esabaGetPokemonID(s32);u32 floorGetCurrent();void heroMoveInitEvent();void heroMoveSetColision(s32);void heroMoveTermEvent();void GSthreadSwitch();void menuIntUnderTakerMenuClose();void menuIntUnderTakerMenuOpen();void winMsgOpen(s32,s32,s32,s32);void winMsgClose(s32);
static void _appearMirabo__Fv();
}
static inline u8 progressBlocked(){u32 progress=GSflagGet(0x3C4);if(progress>=*(u32*)(flag_etc+8+(undertakerdata->progressFirst<<5))&&progress<=*(u32*)(flag_etc+8+(undertakerdata->progressLast<<5)))return 1;return 0;}
static inline u8 firstAvailable(){u32 floor=floorGetCurrent();if(GSflagTest(worldmapXD_data->firstFlag)&&floor!=0x71)return 1;return 0;}
static inline u8 secondAvailable(){u32 floor=floorGetCurrent();s32 flag=worldmapXD_data->secondFlag;if(GSflagTest(0x8D1)&&GSflagTest(flag)&&floor!=0x3B)return 1;return 0;}
static inline UnderTakerPlace *getPlace(s32 index){if(index>=7)return 0;return &undertakerdata->places[index];}
static inline u16 freeSpot(){s32 places[3]={90,91,92};s32 available[3];s32 count=0;for(s32 i=0;i<=2;i++){if(esabaGetPokemonID(i)==0)available[count++]=i;}if(count==0)return 0;return places[available[(u16)HSD_Rand()%count]];}
extern "C" {
void underTakerMenuResore(){}
u32 underTakerGetMiraboPlace(){return GSflagGet(undertakerdata->placeFlag);}
void underTakerMiraboDisAppear(){GSflagSet(undertakerdata->placeFlag,0);GSflagSet(undertakerdata->stepFlag,0);GSflagSet(undertakerdata->countFlag,0);menuIntUnderTakerMenuClose();}
static inline void disappearMessage(){underTakerMiraboDisAppear();heroMoveInitEvent();heroMoveSetColision(1);winMsgOpen(3,0x3E85,1,1);winMsgClose(1);heroMoveTermEvent();}
static inline void announceMirabo(){heroMoveInitEvent();heroMoveSetColision(1);GSthreadSwitch();menuIntUnderTakerMenuOpen();winMsgOpen(3,0x3E84,1,1);winMsgClose(1);menuIntUnderTakerMenuClose();heroMoveTermEvent();}
void underTakerCallBackFunc(s32,s32,u16 steps){if(GSflagTest(undertakerdata->startFlag)&&!GSflagTest(undertakerdata->endFlag)&&darkpokemonCheckUnderTaker()){if((u16)GSflagGet(undertakerdata->placeFlag)==0){u16 elapsed=(u16)GSflagGet(undertakerdata->stepFlag)+steps;if(elapsed>=undertakerdata->interval){u16 increase=undertakerdata->increase;u16 divisor=undertakerdata->randomMax;u16 total=increase+undertakerdata->decrease;u16 random=(u16)HSD_Rand()%divisor;if(random<increase){u16 count=(u16)GSflagGet(undertakerdata->countFlag)+1;if((s32)count>=undertakerdata->maximum-1){if(progressBlocked())count--;else _appearMirabo__Fv();}GSflagSet(undertakerdata->countFlag,count);}else if(random<total){u16 count=GSflagGet(undertakerdata->countFlag);if(count)count--;GSflagSet(undertakerdata->countFlag,count);}elapsed-=undertakerdata->interval;}GSflagSet(undertakerdata->stepFlag,elapsed);return;}if(progressBlocked()){disappearMessage();return;}u16 elapsed=(u16)GSflagGet(undertakerdata->timeFlag)+steps;if(elapsed>=undertakerdata->duration)disappearMessage();GSflagSet(undertakerdata->timeFlag,elapsed);}}
static void _appearMirabo__Fv(){u16 selected;u16 total=0;s32 i=0;UnderTakerPlace *place;while((place=getPlace(i))!=0){total+=place->weight;i++;}u16 random=(u16)HSD_Rand()%total;u16 cumulative=0;i=0;while((place=getPlace(i))!=0){cumulative+=place->weight;if(random<cumulative){selected=place->place;break;}i++;}u32 current=floorGetCurrent();if(selected==undertakerdata->places[0].place){if(!firstAvailable())selected=freeSpot();}else if(selected==undertakerdata->places[1].place){if(!secondAvailable()){if(firstAvailable())selected=undertakerdata->places[0].place;else selected=0;if(!selected)selected=freeSpot();}}else if(selected==undertakerdata->places[2].place){if(esabaGetPokemonID(0)||current==selected){if(firstAvailable())selected=undertakerdata->places[0].place;else selected=0;}}else if(selected==undertakerdata->places[3].place){if(esabaGetPokemonID(1)||current==selected){if(firstAvailable())selected=undertakerdata->places[0].place;else selected=0;}}else if(selected==undertakerdata->places[4].place&&(esabaGetPokemonID(2)||current==selected)){if(firstAvailable())selected=undertakerdata->places[0].place;else selected=0;}if(selected){GSflagSet(undertakerdata->placeFlag,selected);GSflagSet(undertakerdata->timeFlag,0);u8 side=(u16)HSD_Rand()%2;GSflagSet(undertakerdata->sideFlag,side);announceMirabo();return;}GSflagSet(undertakerdata->stepFlag,0);GSflagSet(undertakerdata->countFlag,(u16)(undertakerdata->maximum-2));}
s32 undertakerGetPlace(s32 *output){s32 count=0;if(GSflagTest(undertakerdata->startFlag)&&!GSflagTest(undertakerdata->endFlag)&&darkpokemonCheckUnderTaker()){s32 places[7];s32 i=0;UnderTakerPlace *place;while((place=getPlace(i))!=0){places[i]=place->place;i++;}output[0]=0;count=1;if(!firstAvailable())output[count++]=places[0];if(!secondAvailable())output[count++]=places[1];for(s32 j=0;j<=2;j++){if(esabaGetPokemonID(j)==0)output[count++]=places[j+2];}}return count;}
void undertakerSetPlace(s32 place){GSflagSet(undertakerdata->placeFlag,place);GSflagSet(undertakerdata->timeFlag,0);u8 side=(u16)HSD_Rand()%2;GSflagSet(undertakerdata->sideFlag,side);announceMirabo();}
s32 undertakerGetStartFlagID(){return undertakerdata->startFlag;}
}
